import zipfile, re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_letter(ref):
    return re.match(r'[A-Z]+', ref).group(0)

def col_index(letters):
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1  # 0-based

def row_index(ref):
    return int(re.search(r'\d+', ref).group(0)) - 1  # 0-based

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print('ZIP contents:')
    for n in names:
        print('  ', n)

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            parts = [t.text or '' for t in si.iter('{%s}t' % NS['m'])]
            shared.append(''.join(parts))

    # workbook sheets
    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = wb_root.find('m:sheets', NS)
    sheet_names = [s.get('name') for s in sheets.findall('m:sheet', NS)]
    print('\nSheets:', sheet_names)

    # rels
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels_root.findall('{http://schemas.openxmlformats.org/package/2006/relationships}Relationship'):
        rel_map[rel.get('Id')] = rel.get('Target')

    for sheet_el in sheets.findall('m:sheet', NS):
        rid = sheet_el.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        target = rel_map.get(rid, '')
        path = 'xl/' + target if not target.startswith('/') else target[1:]
        print(f'\n===== Sheet: {sheet_el.get("name")} ({path}) =====')
        ws_root = ET.fromstring(z.read(path))
        sd = ws_root.find('m:sheetData', NS)
        for row_el in sd.findall('m:row', NS):
            for c in row_el.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v_el = c.find('m:v', NS)
                isel = c.find('m:is', NS)
                if v_el is None and isel is None:
                    continue
                if t == 's':
                    val = shared[int(v_el.text)]
                elif t == 'inlineStr':
                    val = ''.join(tt.text or '' for tt in isel.iter('{%s}t' % NS['m']))
                elif t == 'b':
                    val = v_el.text == '1'
                elif t == 'str' or v_el is None:
                    val = v_el.text if v_el is not None else ''
                else:
                    val = v_el.text
                # numeric conversion
                if isinstance(val, str):
                    try:
                        f = float(val)
                        val = int(f) if f.is_integer() else f
                    except ValueError:
                        pass
                print(f'  {ref}: {val!r}')

import zipfile, re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('budget.xlsx') as z:
    ws_root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    # print all cells including formula and style info
    for row_el in ws_root.find('m:sheetData', NS).findall('m:row', NS):
        r = row_el.get('r')
        hidden = row_el.get('hidden')
        if hidden:
            print(f'row {r}: HIDDEN={hidden}')
        for c in row_el.findall('m:c', NS):
            f = c.find('m:f', NS)
            v = c.find('m:v', NS)
            if f is not None:
                print(f"  {c.get('r')}: FORMULA ={f.text}  cached={v.text if v is not None else None}  style={c.get('s')}")
    # check sheet dimension / hidden columns
    dim = ws_root.find('m:dimension', NS)
    print('dimension:', dim.get('ref'))
    cols = ws_root.find('m:cols', NS)
    if cols is not None:
        for col in cols.findall('m:col', NS):
            if col.get('hidden') == '1':
                print('HIDDEN COLUMN:', col.attrib)
    # check for merge cells
    mc = ws_root.find('m:mergeCells', NS)
    if mc is not None:
        print('merge cells:', [m.get('ref') for m in mc.findall('m:mergeCell', NS)])
    else:
        print('merge cells: none')

